use anyhow::{bail, Result};
use unicodex_core::{cid_for_bytes, decode_node, Node, ObjectStore, Value};

use super::super::foreign_process;
use crate::program_module::{eval_module, resolution::resolve_module_entry};
use crate::program_value::{ensure_program_value, program_body, program_kind};

pub(in crate::program_module::runtime) struct LiteralProbe {
    pub(in crate::program_module::runtime) program_cid: String,
    pub(in crate::program_module::runtime) result_cid: String,
    foreign_process: bool,
}

pub(in crate::program_module::runtime) struct PrecommitCandidateProbe {
    pub(in crate::program_module::runtime) program_cid: String,
    pub(in crate::program_module::runtime) result_cid: String,
    pub(in crate::program_module::runtime) foreign_process_readiness:
        Option<foreign_process::readiness::ReadinessObservation>,
}

pub(in crate::program_module::runtime) fn probe_literal_module(
    store: &ObjectStore,
    module_cid: &str,
) -> Result<LiteralProbe> {
    let resolved = resolve_module_entry(store, module_cid, None)?;
    let canonical = store.get_canonical(&resolved.program_cid)?;
    if cid_for_bytes(&canonical) != resolved.program_cid {
        bail!("runtime entry program hash mismatch");
    }
    let program = match decode_node(&canonical)? {
        Node::Value(value) => value,
        _ => bail!("runtime entry program must be a value node"),
    };
    ensure_program_value(&program)?;
    if program_kind(&program) != Some("literal_eval") {
        bail!("module runtime v1 accepts only literal_eval entries");
    }
    let foreign_process = match program_body(&program)? {
        Value::Ref(root_cid) => {
            foreign_process::verify_activation_candidate_if_foreign(store, module_cid, root_cid)?
        }
        _ => false,
    };
    let eval = eval_module(store, module_cid, None)?;
    Ok(LiteralProbe {
        program_cid: resolved.program_cid,
        result_cid: eval.eval.result_cid,
        foreign_process,
    })
}

pub(in crate::program_module::runtime) fn probe_precommit_candidate(
    store: &ObjectStore,
    module_cid: &str,
) -> Result<PrecommitCandidateProbe> {
    let literal = probe_literal_module(store, module_cid)?;
    let foreign_process_readiness = literal
        .foreign_process
        .then(|| foreign_process::readiness::probe(store, module_cid))
        .transpose()?;
    Ok(PrecommitCandidateProbe {
        program_cid: literal.program_cid,
        result_cid: literal.result_cid,
        foreign_process_readiness,
    })
}
